CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,currency text NOT NULL DEFAULT 'BDT',timezone text NOT NULL DEFAULT 'Asia/Dhaka');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),role text NOT NULL CHECK(role IN('ADMIN','MANAGER','RESIDENT')),name text NOT NULL,phone text NOT NULL UNIQUE,password_hash text,active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE login_attempts(key text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE houses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,address text NOT NULL,archived boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id));
CREATE UNIQUE INDEX house_name_idx ON houses(organization_id,lower(name));
CREATE TABLE manager_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,house_id uuid NOT NULL,manager_id uuid NOT NULL,valid_from timestamptz NOT NULL DEFAULT now(),valid_to timestamptz,CHECK(valid_to IS NULL OR valid_to>=valid_from),FOREIGN KEY(organization_id,house_id) REFERENCES houses(organization_id,id),FOREIGN KEY(organization_id,manager_id) REFERENCES users(organization_id,id));
CREATE UNIQUE INDEX current_assignment_idx ON manager_assignments(house_id,manager_id) WHERE valid_to IS NULL;
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,house_id uuid NOT NULL,number text NOT NULL,rent_minor bigint NOT NULL CHECK(rent_minor>=0 AND rent_minor<=1000000000000),created_by uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,house_id) REFERENCES houses(organization_id,id),UNIQUE(house_id,number),UNIQUE(organization_id,id));
CREATE TABLE tenancies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,room_id uuid NOT NULL,resident_id uuid NOT NULL,start_date date NOT NULL,end_date date,cancelled boolean NOT NULL DEFAULT false,created_by uuid NOT NULL REFERENCES users(id),CHECK(end_date IS NULL OR end_date>start_date),FOREIGN KEY(organization_id,room_id) REFERENCES rooms(organization_id,id),FOREIGN KEY(organization_id,resident_id) REFERENCES users(organization_id,id),UNIQUE(organization_id,id),EXCLUDE USING gist(room_id WITH =,daterange(start_date,end_date,'[)') WITH &&) WHERE(NOT cancelled),EXCLUDE USING gist(resident_id WITH =,daterange(start_date,end_date,'[)') WITH &&) WHERE(NOT cancelled));
CREATE TABLE rent_terms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenancy_id uuid NOT NULL REFERENCES tenancies(id),effective_from date NOT NULL,effective_to date,amount_minor bigint NOT NULL CHECK(amount_minor>=0 AND amount_minor<=1000000000000),EXCLUDE USING gist(tenancy_id WITH =,daterange(effective_from,effective_to,'[)') WITH &&));
CREATE TABLE meter_installations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,room_id uuid NOT NULL,serial text NOT NULL,installed_at date NOT NULL,removed_at date,FOREIGN KEY(organization_id,room_id) REFERENCES rooms(organization_id,id),UNIQUE(organization_id,id),EXCLUDE USING gist(organization_id WITH =,serial WITH =,daterange(installed_at,removed_at,'[)') WITH &&),EXCLUDE USING gist(room_id WITH =,daterange(installed_at,removed_at,'[)') WITH &&));
CREATE TABLE meter_readings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),installation_id uuid NOT NULL REFERENCES meter_installations(id),read_at date NOT NULL,reading numeric(14,3) NOT NULL CHECK(reading>=0),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(installation_id,read_at));
CREATE TABLE tariff_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,house_id uuid NOT NULL,effective_from date NOT NULL,rate numeric(12,4) NOT NULL CHECK(rate>=0),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(organization_id,house_id) REFERENCES houses(organization_id,id),UNIQUE(house_id,effective_from),UNIQUE(organization_id,id));
CREATE TABLE bills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,tenancy_id uuid NOT NULL,house_id uuid NOT NULL,room_id uuid NOT NULL,resident_id uuid NOT NULL,type text NOT NULL CHECK(type IN('rent','electricity')),month date NOT NULL,due_date date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>=0 AND amount_minor<=1000000000000),paid_minor bigint NOT NULL DEFAULT 0 CHECK(paid_minor>=0),lifecycle text NOT NULL DEFAULT 'ISSUED' CHECK(lifecycle IN('ISSUED','VOID')),revision integer NOT NULL DEFAULT 1,replaces_id uuid REFERENCES bills(id),scope_owner_id uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(paid_minor<=amount_minor),FOREIGN KEY(organization_id,tenancy_id) REFERENCES tenancies(organization_id,id),FOREIGN KEY(organization_id,house_id) REFERENCES houses(organization_id,id),FOREIGN KEY(organization_id,room_id) REFERENCES rooms(organization_id,id),FOREIGN KEY(organization_id,resident_id) REFERENCES users(organization_id,id),UNIQUE(organization_id,id));
CREATE UNIQUE INDEX active_bill_key_idx ON bills(tenancy_id,type,month) WHERE lifecycle='ISSUED';
CREATE INDEX bills_report_idx ON bills(organization_id,type,month,house_id,created_at DESC,id DESC) WHERE lifecycle='ISSUED';
CREATE TABLE bill_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_id uuid NOT NULL REFERENCES bills(id),installation_id uuid NOT NULL REFERENCES meter_installations(id),previous_reading_id uuid NOT NULL REFERENCES meter_readings(id),current_reading_id uuid NOT NULL REFERENCES meter_readings(id),usage numeric(14,3) NOT NULL CHECK(usage>=0),rate numeric(12,4) NOT NULL CHECK(rate>=0),tariff_id uuid REFERENCES tariff_versions(id));
CREATE UNIQUE INDEX billed_reading_idx ON bill_segments(current_reading_id);
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,bill_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('PAYMENT','REVERSAL')),amount_minor bigint NOT NULL CHECK(amount_minor>0),method text NOT NULL CHECK(method IN('Cash','Bank transfer','bKash','Nagad')),received_at date NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES users(id),receipt_number text NOT NULL UNIQUE DEFAULT ('HL-'||upper(replace(gen_random_uuid()::text,'-',''))),reverses_id uuid UNIQUE REFERENCES payments(id),reason text,CHECK((kind='REVERSAL')=(reverses_id IS NOT NULL)),FOREIGN KEY(organization_id,bill_id) REFERENCES bills(organization_id,id));
CREATE INDEX payments_bill_idx ON payments(bill_id,recorded_at DESC);
CREATE INDEX payments_received_idx ON payments(organization_id,received_at DESC,id DESC);
CREATE TABLE idempotency_records(organization_id uuid NOT NULL,actor_id uuid NOT NULL,route text NOT NULL,key uuid NOT NULL,request_hash text NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,actor_id,route,key));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,resource_id uuid,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_idx ON audit_events(organization_id,created_at DESC,id DESC);
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
